#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdlib.h>

struct NFAState {
    int ruleCount;
    struct transRule** rules;
};

struct transRule {
    struct NFAState* target;
    char cond;
};

void setUp(void) { }
void tearDown(void) { }

void unit_test_createRule_basic_success(void) {
    // Setup: create a dummy NFAState to use as the target
    struct NFAState* state = (struct NFAState*)malloc(sizeof(struct NFAState));
    TEST_ASSERT_NOT_NULL(state);
    state->ruleCount = 0;
    state->rules = NULL;

    char input_char = 'a';

    // Test: call createRule with valid state and character
    struct transRule* rule = createRule(state, input_char);

    // Assertions
    TEST_ASSERT_NOT_NULL(rule);
    TEST_ASSERT_EQUAL_PTR(state, rule->target);
    TEST_ASSERT_EQUAL(input_char, rule->cond);

    // Cleanup
    free(rule);
    free(state);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_createRule_basic_success);
    return UNITY_END();
}

