// Asserts that two ASTs are structurally and content-wise equal.
void helper_assert_ast_equal(struct ASTNode *a, struct ASTNode *b) {
    if (a == NULL && b == NULL) return;
    assert(a != NULL && b != NULL);
    assert(a->content == b->content);
    helper_assert_ast_equal(a->left, b->left);
    helper_assert_ast_equal(a->right, b->right);
}

// Asserts that the NFA compiled from the given regex accepts the given string.
void helper_assert_nfa_accepts(const char *regex, const char *string) {
    char *temp = preProcessing(regex);
    struct ASTNode *node = buildAST(temp);
    struct NFA *nfa = compileFromAST(node);
    postProcessing(nfa);
    nfa->currentStates = realloc(nfa->currentStates, sizeof(struct NFAState*) * 100);
    nfa->currentStates[nfa->CSCount++] = nfa->statePool[0];
    for (size_t i = 0; i < strlen(string); ++i) {
        transit(nfa, '\0');
        transit(nfa, string[i]);
    }
    transit(nfa, '\0');
    assert(isAccepting(nfa) == 1);
    destroyNFA(nfa);
    destroyNode(node);
    free(temp);
}

// Asserts that the NFA compiled from the given regex does not accept the given string.
void helper_assert_nfa_rejects(const char *regex, const char *string) {
    char *temp = preProcessing(regex);
    struct ASTNode *node = buildAST(temp);
    struct NFA *nfa = compileFromAST(node);
    postProcessing(nfa);
    nfa->currentStates = realloc(nfa->currentStates, sizeof(struct NFAState*) * 100);
    nfa->currentStates[nfa->CSCount++] = nfa->statePool[0];
    for (size_t i = 0; i < strlen(string); ++i) {
        transit(nfa, '\0');
        transit(nfa, string[i]);
    }
    transit(nfa, '\0');
    assert(isAccepting(nfa) == 0);
    destroyNFA(nfa);
    destroyNode(node);
    free(temp);
}

